// ==============================================================================
// Testbench: tb_hash_full.sv
// Project:   Ascon AEAD and Hash Engine (NIST SP 800-232)
// Finding:   F1 fix — exhaustive RTL Hash KAT verification
//
// Description:
//   Loops over ALL 1025 NIST SP 800-232 Hash-256 Known Answer Test vectors
//   loaded from tb/vectors/hash_kat.mem (generated by scripts/kat_to_vectors.py).
//
//   Message lengths covered: 0..128 bytes (1025 vectors = lengths 0..1024 bits / 8).
//   Edge-case lengths 0,1,7,8,9,15,16,17,31,32,33,63,64,65,127,128 bytes are
//   present in the KAT set and exercised automatically.
//
//   Result:
//     Writes pass log to results/kat/rtl_hash_full_pass.log.
//     $fatal on first hash mismatch.
//
// Memory layout of hash_kat.mem (RECORD_WORDS = 272):
//   [0]       count
//   [1]       msg_len  (bytes)
//   [2..3]    reserved
//   [4..11]   digest[255:0] big-endian (word4 = digest[255:224])
//   [12..267] message bytes, little-endian packing (256 words = 1024 bytes max)
//
// [SPEC] Requirement: F1 — tb/unit/tb_hash_full.sv must loop over ALL 1025 vectors.
// ==============================================================================

`timescale 1ns / 1ps
`default_nettype wire

module tb_hash_full;

    // -------------------------------------------------------------------------
    // Parameters
    // -------------------------------------------------------------------------
    localparam int NUM_VECTORS     = 1025;
    localparam int RECORD_WORDS    = 272;
    localparam int TOTAL_MEM_WORDS = NUM_VECTORS * RECORD_WORDS; // 278,800

    localparam time CLK_PERIOD = 10ns;

    // -------------------------------------------------------------------------
    // KAT Memory
    // -------------------------------------------------------------------------
    reg [31:0] kat_mem [0:TOTAL_MEM_WORDS-1];

    // -------------------------------------------------------------------------
    // DUT signals
    // -------------------------------------------------------------------------
    reg         clk;
    reg         rst_n;
    reg         start;
    reg         soft_rst;
    reg  [31:0] msg_len;
    reg  [63:0] data_in;
    reg         data_in_valid;
    wire        data_in_ready;
    wire        busy;
    wire        done;
    wire [255:0] digest_out;
    wire [ 3:0] fsm_state;

    // -------------------------------------------------------------------------
    // DUT
    // -------------------------------------------------------------------------
    hash_ctrl dut (
        .clk           (clk),
        .rst_n         (rst_n),
        .start         (start),
        .soft_rst      (soft_rst),
        .msg_len       (msg_len),
        .data_in       (data_in),
        .data_in_valid (data_in_valid),
        .data_in_ready (data_in_ready),
        .busy          (busy),
        .done          (done),
        .digest_out    (digest_out),
        .fsm_state     (fsm_state)
    );

    // -------------------------------------------------------------------------
    // Clock & Watchdog
    // -------------------------------------------------------------------------
    always #(CLK_PERIOD / 2) clk = ~clk;

    initial begin
        #100_000_000;
        $display("\n[FATAL] Hash watchdog timeout");
        $fatal(1, "tb_hash_full watchdog");
    end

    // -------------------------------------------------------------------------
    // Statistics
    // -------------------------------------------------------------------------
    integer total_pass, total_fail;
    integer log_fd;

    // -------------------------------------------------------------------------
    // Helper: soft reset
    // -------------------------------------------------------------------------
    task dut_reset();
        @(negedge clk);
        soft_rst      = 1'b1;
        start         = 1'b0;
        data_in_valid = 1'b0;
        @(negedge clk);
        soft_rst = 1'b0;
        @(negedge clk);
    endtask

    // -------------------------------------------------------------------------
    // Helper: build 64-bit word from little-endian kat_mem layout
    // -------------------------------------------------------------------------
    function automatic [63:0] build_data_word(
        input integer base_word,
        input integer byte_offset
    );
        automatic integer w0 = base_word + (byte_offset / 4);
        automatic integer w1 = w0 + 1;
        automatic reg [31:0] lo = (w0 < TOTAL_MEM_WORDS) ? kat_mem[w0] : 32'h0;
        automatic reg [31:0] hi = (w1 < TOTAL_MEM_WORDS) ? kat_mem[w1] : 32'h0;
        build_data_word = {hi, lo};
    endfunction

    // -------------------------------------------------------------------------
    // Helper: stream N message bytes (8 bytes per beat)
    // -------------------------------------------------------------------------
    task stream_bytes(input integer field_base, input integer num_bytes);
        integer byte_off;
        if (num_bytes == 0) disable stream_bytes;
        byte_off = 0;
        while (byte_off < num_bytes) begin
            wait (data_in_ready == 1'b1);
            @(negedge clk);
            data_in       = build_data_word(field_base, byte_off);
            data_in_valid = 1'b1;
            @(negedge clk);
            data_in_valid = 1'b0;
            byte_off      = byte_off + 8;
        end
    endtask

    // -------------------------------------------------------------------------
    // Build expected 256-bit digest from kat_mem big-endian words
    // -------------------------------------------------------------------------
    function automatic [255:0] expected_digest(input integer base);
        expected_digest = {kat_mem[base+4],  kat_mem[base+5],
                           kat_mem[base+6],  kat_mem[base+7],
                           kat_mem[base+8],  kat_mem[base+9],
                           kat_mem[base+10], kat_mem[base+11]};
    endfunction

    // -------------------------------------------------------------------------
    // MAIN
    // -------------------------------------------------------------------------
    initial begin
        clk           = 1'b0;
        rst_n         = 1'b0;
        start         = 1'b0;
        soft_rst      = 1'b0;
        msg_len       = 32'h0;
        data_in       = 64'h0;
        data_in_valid = 1'b0;
        total_pass    = 0;
        total_fail    = 0;

        $readmemh("tb/vectors/hash_kat.mem", kat_mem);

        log_fd = $fopen("results/kat/rtl_hash_full_pass.log", "w");
        if (log_fd)
            $fdisplay(log_fd, "# tb_hash_full.sv NIST SP 800-232 Hash-256 Exhaustive KAT Log");

        #(CLK_PERIOD * 5);
        @(negedge clk);
        rst_n = 1'b1;
        #(CLK_PERIOD * 2);

        $display("================================================================================");
        $display("tb_hash_full.sv — NIST SP 800-232 Ascon-Hash256 Exhaustive KAT");
        $display("Vectors: 1025 | Msg lengths: 0..1024 bytes");
        $display("================================================================================");

        for (int v = 0; v < NUM_VECTORS; v = v + 1) begin
            automatic integer base      = v * RECORD_WORDS;
            automatic integer v_count   = kat_mem[base + 0];
            automatic integer v_msg_len = kat_mem[base + 1];
            automatic integer msg_base  = base + 12;
            automatic reg [255:0] exp   = expected_digest(base);
            automatic bit is_edge = (v_msg_len inside {0,1,7,8,9,15,16,17,31,32,33,
                                                        63,64,65,127,128});

            dut_reset();

            msg_len = v_msg_len;

            @(negedge clk);
            start = 1'b1;
            @(negedge clk);
            start = 1'b0;

            stream_bytes(msg_base, v_msg_len);

            wait (done == 1'b1);
            @(negedge clk);

            begin
                automatic bit ok = (digest_out === exp);
                if (ok) begin
                    total_pass++;
                    if (is_edge) $display("  [PASS][EDGE] Hash Count=%0d Msg=%0d bytes",
                                          v_count, v_msg_len);
                end else begin
                    total_fail++;
                    $display("  [FAIL] Hash Count=%0d Msg=%0d bytes", v_count, v_msg_len);
                    $display("         got:    %h", digest_out);
                    $display("         expect: %h", exp);
                    if (log_fd) $fdisplay(log_fd, "FAIL Hash Count=%0d", v_count);
                    $fatal(1, "Hash mismatch at Count=%0d", v_count);
                end
            end

            if ((v + 1) % 100 == 0)
                $display("  Progress: %0d / %0d  (PASS=%0d FAIL=%0d)",
                         v + 1, NUM_VECTORS, total_pass, total_fail);

        end // for v

        $display("\n================================================================================");
        $display("tb_hash_full.sv — FINAL RESULT");
        $display("Total PASS: %0d  |  Total FAIL: %0d", total_pass, total_fail);
        $display("================================================================================");

        if (log_fd) begin
            $fdisplay(log_fd, "TOTAL_VECTORS=%0d TOTAL_PASS=%0d TOTAL_FAIL=%0d",
                      NUM_VECTORS, total_pass, total_fail);
            $fdisplay(log_fd, "RESULT=%s", (total_fail == 0) ? "PASS" : "FAIL");
            $fclose(log_fd);
        end

        if (total_fail == 0) begin
            $display("ASCON-HASH256 EXHAUSTIVE KAT: 100%% PASS — ALL 1025 VECTORS VERIFIED (0..1024 bytes)");
            $finish;
        end else begin
            $fatal(1, "tb_hash_full: %0d failures", total_fail);
        end
    end

endmodule

